//! Legacy lifecycle controls for differential integration tests.
//! Kept behind `test-support` so the tests exercise the actual compiled library
//! without copying its private live-mode or reset implementation.

pub fn set_legacy_live_clock(lua: &mlua::Lua, live: bool) {
    if live {
        lua.set_app_data(crate::live::LiveMode(0));
    } else {
        lua.remove_app_data::<crate::live::LiveMode>();
    }
}

pub fn reset_legacy_clock(lua: &mlua::Lua) -> mlua::Result<()> {
    crate::runtime::reset_song_runtime_position(lua)
}

